{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "THBC, a fused tetrahydropyridine secondary amine closely related to the query core, moderately penetrated the BBB in mice after i.v. injection, demonstrating CNS access for this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "HMTIC, a methoxy-tetrahydroisoquinoline, reached rat brain after peripheral administration (0.3–7% of dose), with uptake possibly via the L-aromatic amino acid transporter; this supports transporter-mediated brain entry for polar fused bicyclic amines.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "TIQ readily crossed the BBB in rat in vivo microdialysis, confirming that the tetrahydroisoquinoline/tetrahydropyridine secondary-amine motif is CNS-penetrant.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "2-Pyrrolidinone, a small lactam, rapidly distributed into brain with an AUCbrain/AUCplasma ratio of 53–55%, supporting that small lactam-containing molecules can access the CNS.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "The 7-sulfamoyl-TIQ analogue did not penetrate the BBB due to high polarity, a caution for the query's low logD; however, the query is much smaller and lacks the strongly polar sulfonamide.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C03"],
      "claim": "6-MeO-THBC showed poor BBB penetration in mice, providing a contradictory example within the fused bicyclic amine class; its lower similarity and extra methoxy group limit direct transfer to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The highest-transfer experimental analogues sharing the fused tetrahydropyridine secondary-amine core demonstrate BBB penetration, including transporter-mediated uptake, and the query is a small zwitterionic isoxazolone-piperidine (THIP-like) known to be CNS-active; contradictory polar analogues are less similar and have additional polar/large substituents. Overall, meaningful CNS access is supported.",
  "evidence_gaps": [
    "No direct brain/CSF measurement for the exact query molecule.",
    "Transporter/efflux status of the query is inferred from analogues, not directly measured.",
    "Quantitative brain exposure or unbound brain-to-plasma ratio for the query is not established."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

